import React from "react";
import TeamAnna from "./assets/Team-Anna.png";
import TeamBen from "./assets/Team-Ben.png";
import TeamTom from "../assets/Tim-Tom.png";

const ListNames = [
  {
    id: 1,
    name: "Anna",
    img: TeamAnna,
    description: "Anna brings warmth and energy to our café, making every guest feel right at home.",
  },
  {
    id: 2,
    name: "Ben",
    img: TeamBen,
    description: "Ben crafts each coffee with skill and passion, creating perfect moments in every cup.",
  },
  {
    id: 3,
    name: "Tom",
    img: TeamTom,
    description: "Tom keeps our café running smoothly with his friendly service and attention to detail.",
  },
];

export default ListNames;
